const ProgressCard = ({ title, value, max = 100, color = 'indigo' }) => {
  const colorClasses = {
    indigo: {
      bg: 'bg-indigo-100',
      text: 'text-indigo-800',
      fill: 'bg-indigo-600',
    },
    green: {
      bg: 'bg-green-100',
      text: 'text-green-800',
      fill: 'bg-green-600',
    },
    blue: {
      bg: 'bg-blue-100',
      text: 'text-blue-800',
      fill: 'bg-blue-600',
    },
  };

  return (
    <div className="bg-white overflow-hidden shadow rounded-lg">
      <div className="px-4 py-5 sm:p-6">
        <div className="flex items-center">
          <div className="flex-shrink-0 rounded-full p-3">
            <div className={`h-6 w-6 rounded-full ${colorClasses[color].bg}`}></div>
          </div>
          <div className="ml-5 w-0 flex-1">
            <h3 className="text-lg font-medium text-gray-900">{title}</h3>
            <p className={`text-sm font-medium ${colorClasses[color].text}`}>
              {value} {max !== 100 ? `of ${max}` : '%'}
            </p>
          </div>
        </div>
        <div className="mt-6">
          <div className="w-full bg-gray-200 rounded-full h-2.5">
            <div
              className={`h-2.5 rounded-full ${colorClasses[color].fill}`}
              style={{ width: `${(value / max) * 100}%` }}
            ></div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ProgressCard;
